 $('#cameraSheet').onclick=()=>$('#sheetCameraInput').click();$('#librarySheet').onclick=()=>$('#sheetLibraryInput').click();$$('.open-sheet').forEach(b=>b.onclick=()=>{S.activeSheetId=b.dataset.id;save();currentTab='study';render()});$$('.review-sheet').forEach(b=>b.onclick=()=>{S.activeSheetId=b.dataset.id;save();renderOCRReview(allWords(),false)});setPartner('시험지는 설정에 숨기지 않아. 여기서 바로 열고 확인할 수 있어.','note')
